 void version(){page("app-version","Atualizações do Cineo","Versão instalada: "+a.installedVersion(),()->a.settings());a.call("GET","/version",null,r->{a.title(a.body,"Versão disponível: "+r.optString("version_name"),22);a.text(a.body,r.optString("notes"),14,MUTED);if(r.optInt("version_code")>a.installedCode()&&!r.optString("download_url").isEmpty())a.button(a.body,"Baixar atualização",RED,()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(r.optString("download_url")))));else a.text(a.body,"Seu aplicativo está atualizado.",14,GREEN);});}
 void recommendations(LinearLayout parent){a.socialRequest("GET","/v6/recommend",null,r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)return;ArrayList<JSONObject> shows=new ArrayList<>();for(int i=0;i<rows.length();i++)shows.add(rows.getJSONObject(i));a.shelf(parent,"Dos gêneros que você gosta",shows,false);});}
 void comment(LinearLayout parent,JSONObject c){String author=c.optString("author_id");if(!author.isEmpty()&&!author.equals(a.uid))a.button(parent,"Bloquear esta conta",CARD,()->block(author));if(a.activeShow!=null&&(a.activeShow.optString("owner_id").equals(a.uid)||a.role.equals("admin")))a.button(parent,c.optBoolean("pinned")?"Desafixar comentário":"Fixar comentário",CARD,()->a.safe(()->post("/pin",a.obj("id",c.optInt("id"),"pinned",!c.optBoolean("pinned")),r->{Toast.makeText(a,"Comentário atualizado.",0).show();if(a.commentsDialog!=null)a.commentsDialog.dismiss();})));if(c.optBoolean("pinned"))a.text(parent,"📌 Fixado pelo criador",11,AMBER);}
